python - <<'PY'
import sys;sys.path.insert(0,'/app/output')
from geometry import *
q0=np.array(json.loads((OUT/'latest.json').read_text())['proprio']['now'][:7])
rots=[np.array([[0,-1,0],[0,0,1],[-1,0,0]]),np.array([[0,1,0],[0,0,1],[1,0,0]]),np.array([[0,-1,0],[-1,0,0],[0,0,-1]])]
for i,rot in enumerate(rots):
 for pos in [np.array([-.065,.05,1.06]),np.array([-.065,.367,.866])]:
  def fun(q):
   T=fk(q);return np.r_[(T[:3,3]-pos)*5,R.from_matrix(rot@T[:3,:3].T).as_rotvec()]
  best=None
  for j in range(20):
   seed=q0 if j==0 else np.random.default_rng(j).uniform(LIMITS[:,0]+.01,LIMITS[:,1]-.01)
   opt=least_squares(fun,seed,bounds=(LIMITS[:,0]+.005,LIMITS[:,1]-.005),max_nfev=500)
   score=np.linalg.norm(fun(opt.x))
   if best is None or score<best[0]:best=(score,opt.x)
   if score<.0001:break
  print(i,pos,best[0],np.round(best[1],4))
